<?php
/** Disposable WordPress only: native controls, template ID rewriting, Apply and rollback. */
if(!defined('ABSPATH')||!getenv('SUITEEDGE_QA_EVIDENCE')){exit(1);}
wp_set_current_user(get_user_by('login','qa_admin')->ID);set_current_screen('suiteedge-migrator-mapping');
$checks=0;$check=function($ok,$label)use(&$checks){if(!$ok){throw new RuntimeException('FAIL: '.$label);}$checks++;};
$builder=new SuiteEdge\Migrator\Elementor\DocumentBuilder();$serializer=new SuiteEdge\Migrator\Elementor\Classic\Serializer();$validator=new SuiteEdge\Migrator\Elementor\Validator();
$source='[et_pb_section background_enable_color="off" module_id="default-section"][et_pb_row width="80%" max_width="900px"][et_pb_column type="4_4"][et_pb_text module_id="short-block" module_alignment="center" background_color="#333537" text_text_color="#ffffff" custom_padding="10px|20px|10px|20px" custom_margin="13px||19px||false|false"]<p>Short</p>[/et_pb_text][et_pb_text module_id="capped-block" module_alignment="center" max_width="240px" background_color="#123456"]<p>Width cap</p>[/et_pb_text][et_pb_text module_id="width-block" module_alignment="right" width="60%" width_tablet="70%" width_phone="80%"]<p>Explicit width</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section module_id="transparent-section" background_color="rgba(255,255,255,0)"][et_pb_row][et_pb_column][et_pb_text]Transparent source[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section module_id="gradient-section" background_color__hover="#123456" use_background_color_gradient="on" background_color_gradient_start="rgba(0,0,0,.3)" background_color_gradient_end="rgba(0,0,0,.6)"][et_pb_row][et_pb_column][et_pb_text]Source gradient base[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]';
$data=$serializer->serialize($builder->build($source));$check($validator->validate($data,true)&&!$builder->warnings,'block controls are valid native Elementor settings');
$find=function($nodes,$id)use(&$find){foreach($nodes as$n){if(($n['settings']['_element_id']??'')===$id){return$n;}$child=$find($n['elements'],$id);if($child){return$child;}}return null;};
foreach(['short-block','capped-block']as$id){$n=$find($data,$id);$check($n['settings']['_element_custom_width']['size']===100,'block width control retained: '.$id);}
$library=Elementor\Plugin::$instance->templates_manager->get_source('local');$template=$library->save_item(['title'=>'QA Block layout','type'=>'page','content'=>$data,'page_settings'=>[]]);if(is_wp_error($template)){throw new RuntimeException($template->get_error_message());}$copy=$library->get_data(['template_id'=>$template])['content'];$check($copy[0]['id']!==$data[0]['id']&&$validator->validate($copy,true),'block template insertion rewrites IDs and retains valid data');
$repo=new SuiteEdge\Migrator\Jobs\JobRepository();$runner=new SuiteEdge\Migrator\Jobs\BatchRunner($repo);$backup=new SuiteEdge\Migrator\Import\BackupEngine();$s=(new SuiteEdge\Migrator\Import\SourceRepository())->save(wp_json_encode(['data'=>$source]),'block-layout.json');
$results=[];
foreach(['direct','saved']as$flow){
 $target=wp_insert_post(['post_type'=>'page','post_status'=>'draft','post_title'=>'QA blocks '.$flow,'post_content'=>'Keep body '.$flow]);update_post_meta($target,'_elementor_page_settings',['background_background'=>'classic','background_color'=>'#f4f9fb','custom_css'=>'body{color:#111;}']);update_post_meta($target,'_wp_page_template','default');$before=$backup->fingerprint($target);$page_settings=get_post_meta($target,'_elementor_page_settings',true);
 $job=new SuiteEdge\Migrator\Jobs\Job();$job->settings=['output_engine'=>'classic','dry_run'=>$flow==='saved','assets'=>[]];$job->items=[['source_id'=>$s,'layout_index'=>0,'name'=>'block-layout.json','target_page_id'=>$target,'status'=>'pending']];$job->summary['total']=1;$repo->save($job);$runner->process_batch($job->id);$converted=$repo->get($job->id);
 $check($converted->status==='completed'&&!$converted->items[0]['warnings'],'block '.$flow.' conversion succeeds without warnings');
 if($flow==='saved'){$check($backup->fingerprint($target)===$before,'analyze mode preserves original target');(new SuiteEdge\Migrator\Jobs\SavedOutputApplier())->queue([$job->id=>[0]],true);$runner->process_batch($job->id);$converted=$repo->get($job->id);}
 $check($converted->items[0]['status']==='converted','block '.$flow.' applied');$n=$find($converted->items[0]['elementor_data'],'short-block');$check($n['settings']['_element_custom_width']['size']===100,'native block width survives Apply');$check(get_post_meta($target,'_elementor_page_settings',true)===$page_settings&&get_post_meta($target,'_wp_page_template',true)==='default','destination page background/custom CSS/template assignments not overwritten');
 $report=(new SuiteEdge\Migrator\Reports\ReportBuilder())->build($converted);$check(in_array('export_scope',array_column($report['diagnostics']['entries'],'code'),true),'report explains page export and sitewide template boundary');
 $html=Elementor\Plugin::$instance->frontend->get_builder_content_for_display($target);$check(strpos($html,'Short')!==false&&strpos($html,'margin-left:auto;margin-right:auto;')!==false,'frontend has text and horizontal alignment CSS');
 $runner->rollback($job->id);$check($backup->fingerprint($target)===$before,'exact '.$flow.' rollback restores page');$results[$flow]=['job'=>$job->id,'status'=>$converted->status,'warnings'=>$converted->items[0]['warnings']];
}
$preview=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'QA block surfaces browser']);update_post_meta($preview,'_wp_page_template','elementor_canvas');update_post_meta($preview,'_elementor_edit_mode','builder');Elementor\Plugin::$instance->documents->get($preview)->save(['elements'=>$copy,'settings'=>[]]);(new SuiteEdge\Migrator\Elementor\CssRegenerator())->regenerate($preview);
$results['url']=get_permalink($preview);$results['assertions']=$checks;file_put_contents(getenv('SUITEEDGE_QA_EVIDENCE').'/pools-blocks-'.(defined('DB_ENGINE')?'sqlite':'mariadb').'.json',wp_json_encode($results,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo 'PASS: '.$checks.' block layout WordPress assertions'.PHP_EOL;
